>>> plan_shipments([("ABC-0001", 7)], {"east": {"ABC-0001": 5}, "west": {"ABC-0001": 4}}, ["east", "west"])
{'east': [('ABC-0001', 5)], 'west': [('ABC-0001', 2)]}
"""
remaining = {warehouse: dict(skus) for warehouse, skus in stock.items()}
shipments: dict[str, list[tuple[str, int]]] = {}

for sku, quantity in lines:
    if quantity < 0:
        raise ValueError(f"{sku}: quantity must not be negative")
    if quantity == 0:
        continue

    total = sum(remaining.get(warehouse, {}).get(sku, 0) for warehouse in priority)
    if total < quantity:
        raise InsufficientStock(sku, wanted=quantity, available=total)

    selected = None
    for warehouse in priority:
        if remaining.get(warehouse, {}).get(sku, 0) >= quantity:
            selected = warehouse
            break

    if selected is not None:
        remaining[selected][sku] -= quantity
        shipments.setdefault(selected, []).append((sku, quantity))
    else:
        needed = quantity
        for warehouse in priority:
            if needed == 0:
                break
            available = remaining.get(warehouse, {}).get(sku, 0)
            if available > 0:
                take = min(available, needed)
                remaining[warehouse][sku] = available - take
                shipments.setdefault(warehouse, []).append((sku, take))
                needed -= take

return shipments

